    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or region[r][c] != -1:
                continue
            k = len(is_inside)
            q = deque([(r, c)])
            region[r][c] = k
            touches_edge = False
            while q:
                y, x = q.popleft()
                touches_edge |= y == 0 or y == h - 1 or x == 0 or x == w - 1
                for dy, dx in d4:
                    yy, xx = y + dy, x + dx
