                        region[yy][xx] = k
                        q.append((yy, xx))
            is_inside.append(not touches_edge)

    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen[r][c]:
                continue
